function IpInfoView(props) {
  const data = props.data;
  if (!data) return null;

  // Format location coordinates
  const formatLocation = (locStr) => {
    if (!locStr) return null;
    const [lat, lng] = locStr.split(',');
    return {
      lat: parseFloat(lat),
      lng: parseFloat(lng)
    };
  };

  const location = formatLocation(data.loc);

  const styles = {
    container: {
      backgroundColor: '#ffffff',
      borderRadius: '8px',
      padding: '20px',
      boxShadow: '0 2px 8px rgba(0, 0, 0, 0.1)',
      maxWidth: '800px',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif'
    },
    header: {
      display: 'flex',
      alignItems: 'center',
      marginBottom: '20px'
    },
    ipAddress: {
      fontSize: '22px',
      fontWeight: '600',
      margin: '0'
    },
    hostname: {
      color: '#666',
      marginLeft: '10px',
      fontSize: '14px'
    },
    grid: {
      display: 'grid',
      gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))',
      gap: '20px'
    },
    card: {
      backgroundColor: '#f8f9fa',
      borderRadius: '6px',
      padding: '15px',
      border: '1px solid #eaeaea'
    },
    cardTitle: {
      fontSize: '14px',
      color: '#666',
      marginBottom: '8px',
      textTransform: 'uppercase',
      fontWeight: '500'
    },
    cardValue: {
      fontSize: '16px',
      fontWeight: '500',
      margin: '0',
      wordBreak: 'break-word'
    },
    map: {
      width: '100%',
      height: '300px',
      marginTop: '20px',
      borderRadius: '6px',
      overflow: 'hidden',
      border: '1px solid #eaeaea'
    },
    flag: {
      width: '24px',
      height: '18px',
      marginRight: '8px',
      verticalAlign: 'middle',
      borderRadius: '2px',
      border: '1px solid #eaeaea'
    },
    flagContainer: {
      display: 'flex',
      alignItems: 'center'
    }
  };

  // Function to render a card
  const renderCard = (title, value, icon = null) => {
    if (value === undefined || value === null) return null;

    return React.createElement('div', { style: styles.card },
      React.createElement('div', { style: styles.cardTitle }, title),
      React.createElement('div', { style: styles.cardValue }, 
        icon,
        value
      )
    );
  };

  // Function to render a map
  const renderMap = (lat, lng) => {
    if (!lat || !lng) return null;

    const mapUrl = `https://www.openstreetmap.org/export/embed.html?bbox=${lng-0.01},${lat-0.01},${lng+0.01},${lat+0.01}&layer=mapnik&marker=${lat},${lng}`;

    return React.createElement('div', { style: styles.map },
      React.createElement('iframe', {
        width: '100%',
        height: '100%',
        frameBorder: '0',
        scrolling: 'no',
        marginHeight: '0',
        marginWidth: '0',
        src: mapUrl
      })
    );
  };

  // Function to render country flag
  const renderFlag = (countryCode) => {
    if (!countryCode) return null;

    const flagUrl = `https://flagcdn.com/24x18/${countryCode.toLowerCase()}.png`;

    return React.createElement('span', { style: styles.flagContainer },
      React.createElement('img', {
        src: flagUrl,
        alt: `${countryCode} flag`,
        style: styles.flag
      })
    );
  };

  return React.createElement('div', { style: styles.container },
    // Header with IP address and hostname
    React.createElement('div', { style: styles.header },
      React.createElement('h2', { style: styles.ipAddress }, data.ip),
      data.hostname && React.createElement('span', { style: styles.hostname }, data.hostname)
    ),

    // Information grid
    React.createElement('div', { style: styles.grid },
      data.city && renderCard('City', data.city),
      data.region && renderCard('Region', data.region),
      data.country && renderCard('Country', data.country, renderFlag(data.country)),
      data.postal && renderCard('Postal Code', data.postal),
      data.timezone && renderCard('Timezone', data.timezone),
      data.org && renderCard('Organization', data.org)
    ),

    // Map (if location data is available)
    location && renderMap(location.lat, location.lng)
  );
}

